/// <summary>
/// A stand-in enum for the wire-value tests above. It is declared here rather
/// than taken from the generated models so the test holds for EVERY spec this
/// SDK is generated from — no spec is guaranteed to contain a string enum. It
/// mirrors how the generator emits enums: a [JsonConverter] maps each member to
/// its OpenAPI wire string, which is what ObjectSerializer.Stringify round-trips
/// through.
/// </summary>
[System.Text.Json.Serialization.JsonConverter(typeof(TestHueConverter))]
public enum TestHue
{
    Red,
    Blue,
    Green,
}

public sealed class TestHueConverter : System.Text.Json.Serialization.JsonConverter<TestHue>
{
    public override TestHue Read(
        ref System.Text.Json.Utf8JsonReader reader,
        Type typeToConvert,
        System.Text.Json.JsonSerializerOptions options
    )
    {
        return reader.GetString() switch
        {
            "red" => TestHue.Red,
            "blue" => TestHue.Blue,
            "green" => TestHue.Green,
            _ => throw new System.Text.Json.JsonException(),
        };
    }

    public override void Write(
        System.Text.Json.Utf8JsonWriter writer,
        TestHue value,
        System.Text.Json.JsonSerializerOptions options
    )
    {
        writer.WriteStringValue(
            value switch
            {
                TestHue.Red => "red",
                TestHue.Blue => "blue",
                TestHue.Green => "green",
                _ => throw new System.Text.Json.JsonException(),
            }
        );
    }

    [Fact]
    public void BhvMisc083ARawQueryKeepsItsRepeatedKeysValuesAndEscapesAsWritten()
    {
        Assert.Equal(
            "a=1&a=2&b=%20x",
            ValueSerializer.EncodeQueryAllowingReserved("a=1&a=2&b=%20x")
        );
    }

    [Fact]
    public void BhvMisc084ASetOptionalScalarIsSentInEveryLocation()
    {
        int? value = 7;
        Assert.Equal("7", ValueSerializer.ToPathValue(value));
        Assert.Equal("7", ValueSerializer.ToHeaderValue(value));
    }

    [Fact]
    public void BhvMisc086AnElementHoldingJsonTextIsNotDecodedAgain()
    {
        object? result = ValueSerializer.SerializeStyled(
            "tags",
            new[] { "{\"a\":1}" },
            "query",
            "array",
            null,
            "form",
            false
        );
        Assert.Contains(
            "%7B%22a%22:1%7D",
            result?.ToString() ?? string.Empty,
            StringComparison.Ordinal
        );
    }

    [Fact]
    public void BhvSerialization015MatrixAndLabelStylesExpandAnObjectPerTheExplodeFlag()
    {
        var category = new Category { Id = 3, Name = "lab" };
        Assert.Equal(
            ";id=3;name=lab",
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, "matrix", true)
        );
        Assert.Equal(
            ";c=id,3,name,lab",
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, "matrix", false)
        );
        Assert.Equal(
            ".id=3.name=lab",
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, "label", true)
        );
        Assert.Equal(
            ".id,3,name,lab",
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, "label", false)
        );
    }

    [Theory]
    [InlineData("spaceDelimited", "id 3 name lab")]
    [InlineData("pipeDelimited", "id|3|name|lab")]
    public void BhvSerialization016ObjectInADelimitedStyleIsAlternatingKeysAndValues(
        string style,
        string expected
    )
    {
        var category = new Category { Id = 3, Name = "lab" };
        Assert.Equal(
            expected,
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, style, false)
        );
    }

    [Theory]
    [InlineData("matrix")]
    [InlineData("label")]
    [InlineData("simple")]
    public void BhvSerialization017ModelObjectParameterUsesWireNamesInDeclarationOrder(string style)
    {
        var category = new Category { Id = 3, Name = "lab" };
        string text = Assert.IsType<string>(
            ValueSerializer.SerializeStyled("c", category, "query", "object", null, style, false)
        );
        Assert.True(
            text.IndexOf("id", StringComparison.Ordinal)
                < text.IndexOf("name", StringComparison.Ordinal)
        );
    }

    [Fact]
    public void BhvSerialization018ANestedObjectInsideAnObjectValuedParameterIsRefused()
    {
        var nested = new Dictionary<string, object?>
        {
            {
                "outer",
                new Dictionary<string, object?> { { "inner", "1" } }
            },
        };
        Assert.Throws<SerializationException>(() =>
            ValueSerializer.SerializeStyled("c", nested, "query", "object", null, "matrix", true)
        );
    }
}
